// Detect Execution Mode (Val 2026) — lägger till dagligt intensivläge.
// Lägen via webhook-body.mode: 'test' | 'export-json' | 'daily' (annars veckovis/schemalagt).
// 'daily' = 24h-fönster + radar-format i HTML (config.dailyMode). Behåller dateFrom/dateTo-override.
const items = $input.all();

const isWebhook = items.some(item => item.json.headers !== undefined);
const mode = isWebhook ? 'webhook' : 'scheduled';
const body = (isWebhook && items[0].json.body) ? items[0].json.body : {};

const dailyMode = body.mode === 'daily' || body.mode === 'dagligt';

let dateFrom = body.dateFrom;
let dateTo = body.dateTo;

if (!dateFrom || !dateTo) {
  const now = new Date();
  const back = new Date(now);
  back.setDate(back.getDate() - (dailyMode ? 1 : 7));  // dagligt = 24h, annars 7 dagar
  dateFrom = back.toISOString().split('T')[0];
  dateTo = now.toISOString().split('T')[0];
}

const testMode = body.mode === 'test';
const exportMode = body.mode === 'export-json';
const shouldSendEmail = !testMode && !exportMode;
const modelOverride = (typeof body.model === 'string') ? body.model : undefined;

return [{
  json: {
    mode,
    testMode,
    exportMode,
    dailyMode,
    shouldSendEmail,
    modelOverride,
    dateFrom,
    dateTo,
    executionTime: new Date().toISOString(),
  },
}];

// FAS1 2026-06-10: källbortfalls-guard — HTTP-fel stoppar inte längre flödet,
// utan ger ett markör-item som Aggregate rapporterar som otillgänglig källa.
const _in = $input.first().json || {};
if (_in.error !== undefined) {
  return [{ json: { source: 'FOI-rapporter', isEmpty: true, sourceUnavailable: 'FOI-rapporter' } }];
}

const foiResponse = $json;
const config = $('Detect Execution Mode').first().json;
const dateFrom = new Date(config.dateFrom);
const dateTo = new Date(config.dateTo);
dateTo.setHours(23, 59, 59, 999);

let allReports = [];

try {
  if (foiResponse.success && Array.isArray(foiResponse.reports)) {
    allReports = foiResponse.reports
      .filter(report => {
        if (!report.date) return false;
        const reportDate = new Date(report.date);
        return reportDate >= dateFrom && reportDate <= dateTo;
      })
      .slice(0, 10)
      .map(report => ({
        source: 'FOI',
        type: 'report',
        title: report.title || `Rapport ${report.reportNo}`,
        date: report.date,
        url: report.sourceUrl || report.pdfUrl || '',
        excerpt: report.title || report.reportNo
      }));
  }
} catch (e) {
  console.error('Error parsing FOI:', e);
}

return allReports.length > 0 ? allReports.map(r => ({ json: r })) : [{ json: { source: 'FOI', isEmpty: true } }];

// FAS1 2026-06-10: källbortfalls-guard — HTTP-fel stoppar inte längre flödet,
// utan ger ett markör-item som Aggregate rapporterar som otillgänglig källa.
const _in = $input.first().json || {};
if (_in.error !== undefined || !_in.data) {
  return [{ json: { source: 'MCF', isEmpty: true, sourceUnavailable: 'MCF' } }];
}

// Parse MCF startsida for nyheter
const html = $json.data || '';
const items = [];

try {
  // Sok efter nyheter/aktuellt-sektioner pa sidan
  // MCF har typiskt nyheter i article-taggar eller nyhet-klasser
  const newsMatches = html.matchAll(/<a[^>]*href="([^"]*(?:nyhet|aktuellt|pressmeddelande)[^"]*)">([^<]+)<\/a>/gi);

  for (const match of newsMatches) {
    const url = match[1].startsWith('http') ? match[1] : `https://www.mcf.se${match[1]}`;
    const title = match[2].trim();

    if (title && title.length > 10) {
      items.push({
        source: 'MCF',
        type: 'news',
        title: title,
        url: url,
        date: new Date().toISOString().split('T')[0],
        excerpt: title
      });
    }
  }

  // Fallback: hitta artiklar pa andra satt
  if (items.length === 0) {
    const articleMatches = html.matchAll(/<article[^>]*>([\s\S]*?)<\/article>/gi);
    for (const match of articleMatches) {
      const content = match[1];
      const titleMatch = content.match(/<h[23][^>]*>([^<]+)<\/h[23]>/);
      const linkMatch = content.match(/<a[^>]*href="([^"]+)"/);

      if (titleMatch) {
        items.push({
          source: 'MCF',
          type: 'news',
          title: titleMatch[1].trim(),
          url: linkMatch ? (linkMatch[1].startsWith('http') ? linkMatch[1] : `https://www.mcf.se${linkMatch[1]}`) : 'https://www.mcf.se',
          date: new Date().toISOString().split('T')[0],
          excerpt: titleMatch[1].trim()
        });
      }
    }
  }
} catch (e) {
  console.error('MCF parse error:', e);
}

// Returnera max 5 nyheter
const limited = items.slice(0, 5);
return limited.length > 0 ? limited.map(i => ({ json: i })) : [{ json: { source: 'MCF', isEmpty: true } }];

// FAS1 2026-06-10: källbortfalls-guard — HTTP-fel stoppar inte längre flödet,
// utan ger ett markör-item som Aggregate rapporterar som otillgänglig källa.
const _in = $input.first().json || {};
if (_in.error !== undefined || !_in.data) {
  return [{ json: { source: 'Carl Heath-bloggen', isEmpty: true, sourceUnavailable: 'Carl Heath-bloggen' } }];
}

const rssXml = $json.data;
const config = $('Detect Execution Mode').first().json;
const dateFrom = new Date(config.dateFrom);
const dateTo = new Date(config.dateTo);
dateTo.setHours(23, 59, 59, 999);

const posts = [];

try {
  const itemMatches = rssXml.matchAll(/<item>([\s\S]*?)<\/item>/g);

  for (const match of itemMatches) {
    const itemXml = match[1];

    const titleMatch = itemXml.match(/<title><!\[CDATA\[(.+?)\]\]><\/title>/) || itemXml.match(/<title>(.+?)<\/title>/);
    const linkMatch = itemXml.match(/<link>(.+?)<\/link>/);
    const pubDateMatch = itemXml.match(/<pubDate>(.+?)<\/pubDate>/);
    const descMatch = itemXml.match(/<description><!\[CDATA\[([\s\S]+?)\]\]><\/description>/) || itemXml.match(/<description>([\s\S]+?)<\/description>/);

    if (titleMatch && linkMatch && pubDateMatch) {
      const pubDate = new Date(pubDateMatch[1]);

      if (pubDate >= dateFrom && pubDate <= dateTo) {
        let description = descMatch ? descMatch[1] : '';
        description = description.replace(/<[^>]+>/g, '').substring(0, 300);

        posts.push({
          source: 'Carl Heath',
          type: 'blog',
          title: titleMatch[1],
          url: linkMatch[1],
          date: pubDate.toISOString().split('T')[0],
          excerpt: description
        });
      }
    }
  }
} catch (e) {
  console.error('RSS parse error:', e);
}

return posts.length > 0 ? posts.map(p => ({ json: p })) : [{ json: { source: 'Carl Heath', isEmpty: true } }];

// FAS1 2026-06-10: källbortfalls-guard — HTTP-fel stoppar inte längre flödet,
// utan ger ett markör-item som Aggregate rapporterar som otillgänglig källa.
const _in = $input.first().json || {};
if (_in.error !== undefined || !_in.data) {
  return [{ json: { source: 'One Useful Thing', isEmpty: true, sourceUnavailable: 'One Useful Thing' } }];
}

const rssXml = $json.data;
const config = $('Detect Execution Mode').first().json;
const dateFrom = new Date(config.dateFrom);
const dateTo = new Date(config.dateTo);
dateTo.setHours(23, 59, 59, 999);

const posts = [];

try {
  const itemMatches = rssXml.matchAll(/<item>([\s\S]*?)<\/item>/g);

  for (const match of itemMatches) {
    const itemXml = match[1];

    const titleMatch = itemXml.match(/<title><!\[CDATA\[(.+?)\]\]><\/title>/) || itemXml.match(/<title>(.+?)<\/title>/);
    const linkMatch = itemXml.match(/<link>(.+?)<\/link>/);
    const pubDateMatch = itemXml.match(/<pubDate>(.+?)<\/pubDate>/);
    const descMatch = itemXml.match(/<description><!\[CDATA\[([\s\S]+?)\]\]><\/description>/) || itemXml.match(/<description>([\s\S]+?)<\/description>/);

    if (titleMatch && linkMatch && pubDateMatch) {
      const pubDate = new Date(pubDateMatch[1]);

      if (pubDate >= dateFrom && pubDate <= dateTo) {
        let description = descMatch ? descMatch[1] : '';
        description = description.replace(/<[^>]+>/g, '').substring(0, 300);

        posts.push({
          source: 'One Useful Thing',
          type: 'blog',
          title: titleMatch[1],
          url: linkMatch[1],
          date: pubDate.toISOString().split('T')[0],
          excerpt: description
        });
      }
    }
  }
} catch (e) {
  console.error('RSS parse error:', e);
}

return posts.length > 0 ? posts.map(p => ({ json: p })) : [{ json: { source: 'One Useful Thing', isEmpty: true } }];

// Max 5 kurerade artiklar per veckobrev
const MAX_CURATED_ARTICLES = 5;

const items = $input.all();
const config = $('Detect Execution Mode').first().json;
const dateFrom = new Date(config.dateFrom);
const dateTo = new Date(config.dateTo);
dateTo.setHours(23, 59, 59, 999);

const filteredItems = [];

items.forEach(item => {
  const row = item.json;
  if (!row.url || !row.title) return;

  let dateAdded;
  try {
    dateAdded = new Date(row.date_added);
    if (isNaN(dateAdded.getTime())) return;
  } catch (e) {
    return;
  }

  if (dateAdded >= dateFrom && dateAdded <= dateTo) {
    filteredItems.push({
      json: {
        url: row.url.trim(),
        title: row.title.trim(),
        category: row.category || '',
        dateAdded: row.date_added,
        sheetRowIndex: item.index + 2
      }
    });
  }
});

// Begränsa till max 5 artiklar (senaste först)
const limited = filteredItems
  .sort((a, b) => new Date(b.json.dateAdded) - new Date(a.json.dateAdded))
  .slice(0, MAX_CURATED_ARTICLES);

console.log('Kurerade artiklar: ' + filteredItems.length + ' hittade, ' + limited.length + ' inkluderas (max ' + MAX_CURATED_ARTICLES + ')');

return limited.length > 0
  ? limited
  : [{ json: { source: 'Curated Articles', isEmpty: true } }];

const items = $input.all();
const originalItems = $('Filter Active URLs').all();
const parsedArticles = [];

items.forEach((item, idx) => {
  if (item.json.isEmpty) {
    parsedArticles.push(item);
    return;
  }

  const originalData = originalItems[idx]?.json || {};

  if (item.error || !item.json) {
    parsedArticles.push({
      json: {
        source: 'Curated Articles',
        type: 'curated',
        title: originalData.title || 'Utan titel',
        url: originalData.url || '',
        date: originalData.dateAdded || '',
        category: originalData.category || '',
        excerpt: '[Artikelinnehall kunde inte hamtas]',
        error: true
      }
    });
    return;
  }

  let content = '';
  let excerpt = '';

  try {
    if (item.json.data && item.json.data.content) {
      content = item.json.data.content;
    } else if (typeof item.json === 'string') {
      content = item.json;
    } else if (item.json.content) {
      content = item.json.content;
    }

    excerpt = content
      .replace(/#+\s/g, '')
      .replace(/\[([^\]]+)\]\([^\)]+\)/g, '$1')
      .replace(/\*\*/g, '')
      .replace(/\n\n+/g, ' ')
      .trim()
      .substring(0, 500);

    if (content.length > 500) excerpt += '...';
  } catch (e) {
    excerpt = '[Tolkningsfel]';
  }

  parsedArticles.push({
    json: {
      source: 'Curated Articles',
      type: 'curated',
      title: originalData.title || 'Utan titel',
      url: originalData.url || '',
      date: originalData.dateAdded || '',
      category: originalData.category || '',
      excerpt: excerpt || content.substring(0, 500),
      fullContent: content.substring(0, 2000),
      error: false
    }
  });
});

return parsedArticles;

// STRIKT FILTER: Endast citat fran senaste 7 dagarna
// Citat UTAN datum exkluderas (tidigare fick de dagens datum)
const items = $input.all();

const now = new Date();
const sevenDaysAgo = new Date(now);
sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);
sevenDaysAgo.setHours(0, 0, 0, 0);

const quotes = [];

console.log('=== CITATFILTER ===' );
console.log('Godkanner endast citat fran:', sevenDaysAgo.toISOString().split('T')[0], 'till', now.toISOString().split('T')[0]);

items.forEach(item => {
  const row = item.json;

  const quoteVal = row.quote || row.Quote || row.citat || row.Citat || row.text || row.Text || '';
  const sourceVal = row.source || row.Source || row.kalla || row.Kalla || '';
  const contextVal = row.context || row.Context || row.kontext || row.Kontext || '';
  const urlVal = row.url || row.URL || row.Url || row.link || row.Link || '';
  const dateVal = row.date_added || row.dateAdded || row.date || row.Date || row.datum || row.Datum || '';

  if (!quoteVal || !sourceVal) {
    return;
  }

  // STRIKT: Datum MASTE finnas
  if (!dateVal) {
    console.log('EXKLUDERAD (saknar datum):', sourceVal);
    return;
  }

  const dateAdded = new Date(dateVal);

  // STRIKT: Datum maste vara giltigt
  if (isNaN(dateAdded.getTime())) {
    console.log('EXKLUDERAD (ogiltigt datumformat):', sourceVal, '- varde:', dateVal);
    return;
  }

  // STRIKT: Maste vara inom senaste 7 dagarna
  if (dateAdded < sevenDaysAgo) {
    console.log('EXKLUDERAD (for gammalt):', sourceVal, '- datum:', dateVal);
    return;
  }

  if (dateAdded > now) {
    console.log('EXKLUDERAD (framtida):', sourceVal, '- datum:', dateVal);
    return;
  }

  // Godkand!
  quotes.push({
    json: {
      type: 'manual_quote',
      quote: quoteVal.trim(),
      source: sourceVal.trim(),
      context: contextVal || '',
      url: urlVal || '',
      dateAdded: dateAdded.toISOString().split('T')[0]
    }
  });
  console.log('GODKAND:', sourceVal, '- datum:', dateVal);
});

console.log('=== RESULTAT: ' + quotes.length + ' citat godkanda ===' );

return quotes.length > 0 ? quotes : [{ json: { type: 'manual_quote', isEmpty: true } }];

// FAS1 2026-06-10: källbortfalls-guard — HTTP-fel stoppar inte längre flödet,
// utan ger ett markör-item som Aggregate rapporterar som otillgänglig källa.
const _in = $input.first().json || {};
if (_in.error !== undefined || !_in.data) {
  return [{ json: { source: 'Regeringen (RSS)', isEmpty: true, sourceUnavailable: 'Regeringen (RSS)' } }];
}

// Parse Regeringen RSS-flode for nyheter om civilt forsvar/totalforsvar
const rssXml = $json.data || '';
const config = $('Detect Execution Mode').first().json;
const dateFrom = new Date(config.dateFrom);
const dateTo = new Date(config.dateTo);
dateTo.setHours(23, 59, 59, 999);

const posts = [];

try {
  const itemMatches = rssXml.matchAll(/<item>([\s\S]*?)<\/item>/g);

  for (const match of itemMatches) {
    const itemXml = match[1];

    // Hantera bade CDATA och vanlig text
    const titleMatch = itemXml.match(/<title><!\[CDATA\[(.+?)\]\]><\/title>/) || itemXml.match(/<title>(.+?)<\/title>/);
    const linkMatch = itemXml.match(/<link><!\[CDATA\[(.+?)\]\]><\/link>/) || itemXml.match(/<link>(.+?)<\/link>/);
    const pubDateMatch = itemXml.match(/<pubDate>(.+?)<\/pubDate>/);
    const descMatch = itemXml.match(/<description><!\[CDATA\[([\s\S]+?)\]\]><\/description>/) || itemXml.match(/<description>([\s\S]+?)<\/description>/);

    if (titleMatch && linkMatch) {
      let pubDate = new Date();
      if (pubDateMatch) {
        pubDate = new Date(pubDateMatch[1]);
      }

      // Filtrera pa datum
      if (pubDate >= dateFrom && pubDate <= dateTo) {
        let description = descMatch ? descMatch[1] : '';
        description = description.replace(/<[^>]+>/g, '').trim().substring(0, 300);

        posts.push({
          source: 'Regeringen',
          type: 'government',
          title: titleMatch[1].trim(),
          url: linkMatch[1].trim(),
          date: pubDate.toISOString().split('T')[0],
          excerpt: description || titleMatch[1].trim()
        });
      }
    }
  }
} catch (e) {
  console.error('Regeringen RSS parse error:', e);
}

const limited = posts.slice(0, 10);
return limited.length > 0 ? limited.map(p => ({ json: p })) : [{ json: { source: 'Regeringen', isEmpty: true } }];

// Aggregate (Val 2026) — samlar valbevakningskällor + Riksdag + tema-kontinuitet.
// Ersätter "Aggregate All Results" i den klonade workflowen.
// Läser DIREKT från Parse-noderna (undviker n8n Merge typeVersion 3.2-buggen).
// Källkeys måste matcha sourceKey i Source Config (Val 2026).
const unavailableSources = [];

const readSource = (nodeName) => {
  try {
    const items = $(nodeName).all().map(i => i.json).filter(j => j);
    items.forEach(j => {
      if (j.sourceUnavailable && !unavailableSources.includes(j.sourceUnavailable)) {
        unavailableSources.push(j.sourceUnavailable);
      }
    });
    return items.filter(j => !j.isEmpty);
  } catch (e) {
    console.log(`Kunde inte lasa fran ${nodeName}: ${e.message}`);
    return [];
  }
};

const fas3 = readSource('Parse Sources (Fas 3)');
const byKey = (k) => fas3.filter(j => j.sourceKey === k);

const response = {
  success: true,
  executionTime: new Date().toISOString(),
  sources: {
    // Nyhetsmedier
    svt:            byKey('svt'),
    svtvast:        byKey('svtvast'),
    gp:             byKey('gp'),
    // Officiell valmyndighet
    valmyndigheten: byKey('valmynd'),
    // Säkerhet & påverkansbevakning
    mpf:            byKey('mpf'),
    msb:            byKey('msb'),
    sapo:           byKey('sapo'),
    foi:            byKey('foi'),
    certse:         byKey('certse'),
    euvsdisinfo:    byKey('euvsdisinfo'),
    // Riksdagsdokument/voteringar/kalender — befintliga noder, söksträngar omriktade
    // mot vallag/demokrati (se BUILD.md, Compute Riksdag Date Range / Fetch Riksdag Documents).
    riksdagDocuments: readSource('Parse Riksdag Documents'),
    riksdagVotes:     readSource('Parse Riksdag Votes'),
    riksdagCalendar:  readSource('Parse Riksdag Calendar'),
    // Tema-kontinuitet 2026 — föregående perioders arkiverade teman (Notion Val2026-Teman)
    previousWeeks:    readSource('Parse Previous Themes').filter(j => j.type === 'previous_week'),
  },
  totalItems: 0,
  unavailableSources,
};

response.totalItems = Object.values(response.sources)
  .reduce((sum, arr) => sum + arr.length, 0);

// VG-flagga: deterministisk geografisk märkning (samma termlista som beredskapssektorer-brevet).
// Nationell bevakning → VG markeras som sekundär flagga. Parametrisera vgTerms för annat län.
const normalizeUrl = (u) => (typeof u === 'string' && u.startsWith('//')) ? 'https:' + u : u;
const vgTerms = ['västra götaland','göteborg','trollhättan','vänersborg','borås','skövde',
  'uddevalla','mariestad','lidköping','civilområde väst','civo v','sjuhärad','skaraborg',
  'bohuslän','dalsland','vänern','stenungsund','lysekil','landvetter','göta älv','strömstad'];
let vgFlaggedCount = 0;
Object.values(response.sources).forEach(arr => arr.forEach(item => {
  if (item && typeof item === 'object') {
    if (item.url) item.url = normalizeUrl(item.url);
    if (typeof item.title === 'string') item.title = item.title.trim();
    const blob = ((item.title || '') + ' ' + (item.excerpt || '') + ' ' + (item.fulltext || '') + ' ' + (item.titel || '')).toLowerCase();
    if (blob.trim() && vgTerms.some(t => blob.includes(t))) {
      item.vgFlagga = true;
      vgFlaggedCount++;
    }
  }
}));
response.vgFlaggedCount = vgFlaggedCount;

return [{ json: response }];

// Prepare Synthesis Request (Val 2026) — fyra fasta valteman + källkritik + tema-kontinuitet.
// Ersätter "Prepare Synthesis Request" i den klonade workflowen.
// Läser Aggregate (Val 2026) → s.<källa>, samt s.previousWeeks ur Notion-arkivet.
// Domänkontext bakas in INLINE (ingen Google Sheet-beroende som i civiltforsvar).
// Output-JSON konsumeras av Parse Synthesis Response (generisk) och webhook export-json.

const aggregatedData = $('Aggregate All Results').first().json;
const config = $('Detect Execution Mode').first().json;
const s = aggregatedData.sources;

// === Generisk källistrenderare ===
function renderList(label, arr, opts) {
  opts = opts || {};
  arr = arr || [];
  if (opts.skipEmpty && arr.length === 0) return '';
  let out = '\n' + label + ' (' + arr.length + '):\n';
  arr.forEach((item, i) => {
    out += (i + 1) + '. ' + (item.title || item.titel || '') + '\n';
    if (item.date || item.datum) out += '   Datum: ' + (item.date || item.datum) + '\n';
    if (item.url) out += '   URL: ' + item.url + '\n';
    if (item.excerpt) out += '   Utdrag: ' + item.excerpt + '\n';
    if (item.vgFlagga) out += '   [VG-FLAGGA: trolig Västra Götaland-koppling]\n';
    out += '\n';
  });
  return out;
}

// === Underlag ===
let contentSummary = 'Datumintervall: ' + config.dateFrom + ' till ' + config.dateTo + '\n\n';
contentSummary += '=== NYHETSMEDIER ===';
contentSummary += renderList('SVT NYHETER', s.svt, { skipEmpty: true });
contentSummary += renderList('SVT VÄSTNYTT', s.svtvast, { skipEmpty: true });
contentSummary += renderList('GÖTEBORGS-POSTEN', s.gp, { skipEmpty: true });
contentSummary += '\n=== OFFICIELL VALMYNDIGHET ===';
contentSummary += renderList('VALMYNDIGHETEN', s.valmyndigheten, { skipEmpty: true });
contentSummary += '\n=== SÄKERHET & PÅVERKANSBEVAKNING ===';
contentSummary += renderList('MYNDIGHETEN FÖR PSYKOLOGISKT FÖRSVAR (MPF)', s.mpf, { skipEmpty: true });
contentSummary += renderList('MSB', s.msb, { skipEmpty: true });
contentSummary += renderList('SÄKERHETSPOLISEN', s.sapo, { skipEmpty: true });
contentSummary += renderList('FOI', s.foi, { skipEmpty: true });
contentSummary += renderList('CERT-SE (CYBERINCIDENTER)', s.certse, { skipEmpty: true });
contentSummary += renderList('EUVSDISINFO (INTERNATIONELL PÅVERKAN)', s.euvsdisinfo, { skipEmpty: true });

// Riksdagsdokument — prioritera valrelaterade (_kwHit) först, ta topp 10.
const rdDocs = (s.riksdagDocuments || [])
  .slice()
  .sort((a, b) => (b._kwHit ? 1 : 0) - (a._kwHit ? 1 : 0))
  .slice(0, 10);
if (rdDocs.length) {
  contentSummary += '\n=== RIKSDAGSDOKUMENT (vallag/demokrati prioriterat) ===\n';
  rdDocs.forEach((d, i) => {
    contentSummary += (i + 1) + '. [' + (d.doktyp || '').toUpperCase() + ' ' + (d.beteckning || '') + '] ' + (d.titel || '') + '\n' +
      '   Datum: ' + (d.datum || '') + ' | URL: ' + (d.url || '') + (d._kwHit ? '\n   [VAL-RELEVANT]' : '') + '\n' +
      (d.excerpt ? '   Utdrag: ' + d.excerpt + '\n' : '') + '\n';
  });
}

// Riksdagens kalender (kommande 7 dagar) — underlag för upcomingWeek
const rdCal = (s.riksdagCalendar || []).slice(0, 15);
if (rdCal.length) {
  contentSummary += '\n=== RIKSDAGENS KALENDER (kommande, för "inkommande") ===\n';
