  if (!data) return;
  // Identifiera vilken sida baserat på innehåll
  if (data.includes('/nyheter/') && data.includes('datetime=')) {
    newsHtml = data;
  }
  if (data.includes('/publikationer/')) {
    rapporterHtml = data;
  }
});

// Parsa nyheter
try {
  const timeRegex = /<time\s+datetime="([^"]+)"[^>]*>[^<]*<\/time>[\s\S]*?<a\s+href="(\/nyheter\/[^"]+)"[^>]*>([^<]+)<\/a>/g;
  let match;
  while ((match = timeRegex.exec(newsHtml)) !== null) {
    const pubDate = new Date(match[1]);
    if (pubDate >= dateFrom && pubDate <= dateTo) {
      results.push({
        source: 'MTFA',
        type: 'news',
        title: match[3].trim(),
        url: 'https://www.mtfa.se' + match[2],
        date: pubDate.toISOString().split('T')[0],
        excerpt: match[3].trim()
      });
    }
  }
} catch (e) {
  console.error('MTFA nyheter parse error:', e);
}

// Parsa rapporter
try {
  const pubRegex = /<a\s+href="(\/publikationer\/[^"]+)"[^>]*>([^<]+)<\/a>/g;
  let match;
  const seen = new Set();
  while ((match = pubRegex.exec(rapporterHtml)) !== null) {
    const url = 'https://www.mtfa.se' + match[1];
    const title = match[2].trim();
    if (title === 'Läs mer och ladda hem') continue;
    if (seen.has(url)) continue;
    seen.add(url);
    results.push({
      source: 'MTFA',
      type: 'report',
      title: title,
      url: url,
      date: '',
      excerpt: title
    });
  }
} catch (e) {
  console.error('MTFA rapporter parse error:', e);
}

