// EXACT_TOKENS: matchar ENBART som komplett slug-token (mellan bindestreck).
// Ascii-normaliserade.
const EXACT_TOKENS = new Set([
  // Forsvar / totalforsvar / beredskap
  'forsvar','totalforsvar','civilforsvar','varnplikt','militar','militaer',
  'hemvarn','folkforsvar','civilplikt','overstebefalhavare','beredskap',
