  // Ostersjon / maritimt
  'ostersjon','ostersjo','skuggflott','skuggflotta','skuggflottan',
  'undervatten','sjokabel','sjokablar','nord-stream','nordstream','baltic',
  // Kritisk infrastruktur
  'infrastruktur','kraftverk','karnkraftverk','elnat','elproduktion',
  'gasnat','gas','olja','oljepris','vattenverk','livsmedelsforsorjning',
  'flygplats','telekom',
  // Geopolitik / allianser
  'allians','gransbevak','gransskydd','transatlantisk','transatlantiska',
  'stoltenberg','rutte','eu-toppmote','eu-budget','eu-stod','g7','g20',
  // Krig / kris / vapen
  'krig','krigsforbrytelser','kris','krisberedskap','attack','attacken',
  'attacker','vapen','vapensystem','vapensmuggl','luftvarn','ammunition',
  'missil','missiler','robotar','stridsvagn','stridsvagnar','strids',
