  'sakerhetsskydd','sakerhetsskyddsbrist','sakerhetsklassning','klassad',
  'klassning','hemligstamplad','underrattelsetjanst','underrattelse'
]);

// PHRASE_PATTERNS: matchas mot full slug-strang (efter normalisering).
// Anvands for fraser som spannar over flera tokens.
const PHRASE_PATTERNS = [
  /\beu-toppmote\b/, /\bnord-stream\b/, /\bvit-rysk/, /\broda-havet\b/,
  /\bsvart-hav\b/, /\bdraknase\b/, /\bfarligt-foremal\b/, /\bterrorhot\b/
];

const items = $input.all();
const raw = items[0]?.json;
let xmlText = '';
if (typeof raw === 'string') xmlText = raw;
else if (raw?.data) xmlText = String(raw.data);
else if (raw?.body) xmlText = String(raw.body);
else xmlText = JSON.stringify(raw || '');

const urlBlocks = xmlText.match(/<url>[\s\S]*?<\/url>/g) || [];
const candidates = [];

urlBlocks.forEach(block => {
  const locMatch = block.match(/<loc>([^<]+)<\/loc>/);
  const lastmodMatch = block.match(/<lastmod>([^<]+)<\/lastmod>/);
  if (!locMatch || !lastmodMatch) return;

  const url = locMatch[1].trim();
  const lastmod = new Date(lastmodMatch[1].trim());
  if (isNaN(lastmod.getTime())) return;
  if (!/\/a\/[A-Za-z0-9]+\/?$/.test(url)) return;
  if (lastmod < dateFrom || lastmod > dateTo) return;

  const slugMatch = url.match(/^https?:\/\/omni\.se\/([^/]+)\/a\//);
  if (!slugMatch) return;
  const slug = slugMatch[1].toLowerCase();
  const slugAscii = slug.normalize('NFD').replace(/[\u0300-\u036f]/g, '');

  // Token-match: dela slug pa bindestreck, matcha mot EXACT_TOKENS
  const tokens = slugAscii.split('-').filter(Boolean);
  let matched = tokens.find(t => EXACT_TOKENS.has(t));

  // Fall tillbaka pa frasmonster (extrahera ren strang ur regexp)
  if (!matched) {
    const phrase = PHRASE_PATTERNS.find(re => re.test(slugAscii));
    if (phrase) {
      const m = slugAscii.match(phrase);
      matched = (m && m[0]) ? m[0] : 'phrase-match';
    }
  }

  if (!matched) return;

  candidates.push({
    url,
    slug,
    lastmod: lastmod.toISOString(),
    matchedKeyword: matched
