// Parser för FOI:s rapporter.html (Jina-rendrad markdown).
// Letar efter FOI-R--XXXX--SE och FOI Memo XXXX, fångar närliggande titlar och datum.
const response = $json;
let content = '';
if (response.data && response.data.content) content = response.data.content;
else if (typeof response === 'string') content = response;
else if (response.content) content = response.content;
else if (response.body) content = response.body;

if (!content) return [{ json: { source: 'FOI', isEmpty: true } }];

const items = [];
const seen = new Set();
const lines = content.split(/\r?\n/);

const reportRegex = /(FOI(?:-R--|\s+Memo\s+)\d{3,5}(?:--SE)?)/g;
const dateRegex = /(\d{4}-\d{2}-\d{2})/;

for (let i = 0; i < lines.length; i++) {
  const line = lines[i];
  const reportMatches = [...line.matchAll(reportRegex)];
  if (reportMatches.length === 0) continue;

  for (const m of reportMatches) {
    const reportNo = m[1].replace(/\s+/g, ' ').trim();
    if (seen.has(reportNo)) continue;
    seen.add(reportNo);

    // Bygg URL — FOI-R rapporter har rapportsammanfattning.html
    let url = '';
    if (/^FOI-R--/.test(reportNo)) {
      url = 'https://www.foi.se/rapporter/rapportsammanfattning.html?reportNo=' + encodeURIComponent(reportNo);
    } else {
      // FOI Memo har annan URL — fallback till sök
      url = 'https://www.foi.se/sok-publikationer.html?query=' + encodeURIComponent(reportNo);
    }

    // Försök hitta länk i samma rad
    const linkMatch = line.match(/\[([^\]]+)\]\((https?:\/\/[^\)]+)\)/);
    if (linkMatch && linkMatch[2].includes(reportNo)) url = linkMatch[2];

    // Titel: kolla samma rad eller närliggande
    let title = '';
    // Samma rad — text efter rapportnumret
    const afterNo = line.substring(line.indexOf(reportNo) + reportNo.length).replace(/^[\s:\-—]+/, '').trim();
    if (afterNo && afterNo.length > 5 && afterNo.length < 250) title = afterNo.replace(/[\[\]\(\)#]/g, '').trim();
    // Om inte titel — kolla föregående rad
    if (!title && i > 0) {
      const prev = lines[i - 1].trim();
      if (prev && prev.length > 5 && prev.length < 250 && !prev.match(reportRegex)) title = prev.replace(/^[\#\*\-\s]+/, '').trim();
    }
    if (!title) title = reportNo;

    // Datum: i samma rad eller ±3
    let date = '';
    for (let j = Math.max(0, i - 3); j <= Math.min(lines.length - 1, i + 3); j++) {
      const dm = lines[j].match(dateRegex);
      if (dm) { date = dm[1]; break; }
    }

    items.push({
      source: 'FOI',
      type: 'report',
      reportNo,
      title,
      url,
      date,
      excerpt: title,
    });
    if (items.length >= 20) break;
  }
  if (items.length >= 20) break;
}

if (items.length === 0) return [{ json: { source: 'FOI', isEmpty: true } }];
return items.map(it => ({ json: it }));

