const monthMap = {januari:1,februari:2,mars:3,april:4,maj:5,juni:6,juli:7,augusti:8,september:9,oktober:10,november:11,december:12};
const MONTHS_RX = 'januari|februari|mars|april|maj|juni|juli|augusti|september|oktober|november|december';

function parseDate(s) {
  if (!s) return null;
  s = String(s).trim();
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return new Date(s.substring(0, 10));
  let m = s.match(new RegExp('(\\d{1,2})\\s+(' + MONTHS_RX + ')\\s+(\\d{4})', 'i'));
  if (m) return new Date(Date.UTC(+m[3], monthMap[m[2].toLowerCase()] - 1, +m[1]));
  m = s.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})$/);
  if (m) return new Date(Date.UTC(+m[3], +m[2] - 1, +m[1]));
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : d;
}
const inWindow = (d) => d && d >= dateFrom && d <= dateTo;
const isoDay = (d) => d.toISOString().split('T')[0];
function stripTags(s) {
  return (s || '').replace(/<!\[CDATA\[|\]\]>/g, '').replace(/<[^>]+>/g, '').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#0?39;/g, "'").replace(/\s+/g, ' ').trim();
}

function parseJina(content, cfg) {
  const items = [];
  const seen = new Set();
  const lines = content.split(/\r?\n/);
  let undated = 0;
  for (let i = 0; i < lines.length; i++) {
    const lm = lines[i].match(/\[([^\]]{8,200})\]\((https?:[^\)]+)\)/);
    if (!lm) continue;
    const title = lm[1].trim();
    const url = lm[2].trim();
    if (/^(Läs mer|Mer info|Kontakt|Sök|Logga in|Hem|Tillbaka|Föregående|Nästa|Relevans|Datum|Sortera.*)$/i.test(title)) continue;
    // Skräpfilter v2: cookie-/navigations-/policylänkar som annars äter undated-cappen
    if (/cookie|kakor|integritetspolicy|personuppgift|tillgänglighet|teckenspråk|lättläst|in english|om webbplatsen|prenumerera|webbkarta|till innehållet|gå direkt till|textinnehållet|microsoft azure|google analytics/i.test(title)) continue;
    if (/^(#|tel:|mailto:|javascript:)/.test(url)) continue;
    if (/policies\.google|cookieinformation|youtube\.com|facebook\.com|linkedin\.com|twitter\.com|instagram\.com/i.test(url)) continue;
    if (seen.has(url)) continue;
    seen.add(url);
    // Per-källa URL-mönster: endast artikellänkar räknas
    if (cfg.urlInclude && !(new RegExp(cfg.urlInclude, 'i')).test(url)) continue;
    let dateStr = '';
    for (let j = Math.max(0, i - 3); j <= Math.min(lines.length - 1, i + 3); j++) {
      const m = lines[j].match(/(\d{4}-\d{2}-\d{2})/) ||
                lines[j].match(new RegExp('(\\d{1,2}\\s+(?:' + MONTHS_RX + ')\\s+\\d{4})', 'i'));
      if (m) { dateStr = m[1]; break; }
    }
    const date = parseDate(dateStr);
    let excerpt = '';
    for (let j = i + 1; j <= Math.min(lines.length - 1, i + 4); j++) {
      const l = lines[j].trim();
      if (l && !l.startsWith('[') && !l.startsWith('#') && !l.startsWith('---') && l.length > 30) {
        excerpt = l.substring(0, 280); break;
      }
    }
    if (date) {
      if (!inWindow(date)) continue;
    } else {
      if (undated >= (cfg.maxUndated || 0)) continue;
      undated++;
    }
    items.push({ sourceKey: cfg.sourceKey, source: cfg.label, type: 'news', title, url, date: date ? isoDay(date) : '', excerpt });
    if (items.length >= cfg.maxItems) break;
  }
  return items;
}

function parseRss(xml, cfg) {
  const items = [];
  const blocks = [...xml.matchAll(/<item[\s>][\s\S]*?<\/item>|<entry[\s>][\s\S]*?<\/entry>/g)].map(m => m[0]);
  for (const b of blocks) {
    const title = stripTags((b.match(/<title[^>]*>([\s\S]*?)<\/title>/) || [])[1] || '');
    let url = '';
    const linkHref = b.match(/<link[^>]*href="([^"]+)"/);
    const linkText = b.match(/<link[^>]*>([\s\S]*?)<\/link>/);
    if (linkHref) url = linkHref[1].trim();
    else if (linkText) url = stripTags(linkText[1]);
    const dateRaw = (b.match(/<pubDate>([\s\S]*?)<\/pubDate>/) || b.match(/<published>([\s\S]*?)<\/published>/) ||
                     b.match(/<updated>([\s\S]*?)<\/updated>/) || b.match(/<dc:date>([\s\S]*?)<\/dc:date>/) || [])[1] || '';
    const date = parseDate(stripTags(dateRaw));
    if (!inWindow(date)) continue;
    if (!title || !url) continue;
    const desc = (b.match(/<description>([\s\S]*?)<\/description>/) || b.match(/<summary[^>]*>([\s\S]*?)<\/summary>/) || [])[1] || '';
    items.push({ sourceKey: cfg.sourceKey, source: cfg.label, type: 'news', title, url, date: isoDay(date), excerpt: stripTags(desc).substring(0, 280) });
    if (items.length >= cfg.maxItems) break;
  }
  return items;
}

function parseHybridcoe(html, cfg) {
  const items = [];
  const chunks = html.split('<a href="').slice(1);
  for (const c of chunks) {
    const url = c.substring(0, c.indexOf('"'));
    if (!/^https:\/\/www\.hybridcoe\.fi\//.test(url)) continue;
    const t = c.match(/liftup-title['"]>([\s\S]*?)<\/h\d>/);
    if (!t) continue;
    const title = stripTags(t[1]);
    if (/^Job opening/i.test(title)) continue;
    const d = c.match(/liftup-date['"]>\s*([\d.]+)\s*</);
    const date = parseDate((d || [])[1] || '');
    if (!inWindow(date)) continue;
    items.push({ sourceKey: cfg.sourceKey, source: cfg.label, type: 'news', title, url, date: isoDay(date), excerpt: '' });
    if (items.length >= cfg.maxItems) break;
  }
  return items;
}

const out = [];
for (let i = 0; i < responses.length; i++) {
  const cfg = configs[i] || {};
  const resp = responses[i].json || {};
  const marker = (unavailable) => ({ json: { source: cfg.label, sourceKey: cfg.sourceKey, isEmpty: true, ...(unavailable ? { sourceUnavailable: cfg.label } : {}) } });
  if (resp.error !== undefined) { out.push(marker(true)); continue; }
  let body = '';
  if (cfg.parser === 'jina') body = (resp.data && resp.data.content) ? resp.data.content : '';
  else if (typeof resp.data === 'string') body = resp.data;
  else if (typeof resp === 'string') body = resp;
  if (!body) { out.push(marker(true)); continue; }
  let items = [];
  try {
    if (cfg.parser === 'jina') items = parseJina(body, cfg);
    else if (cfg.parser === 'rss') items = parseRss(body, cfg);
    else if (cfg.parser === 'hybridcoe') items = parseHybridcoe(body, cfg);
  } catch (e) {
    console.log('Parsefel ' + cfg.sourceKey + ': ' + e.message);
    out.push(marker(true)); continue;
  }
  if (items.length === 0) out.push(marker(false));
  else items.forEach(it => out.push({ json: it }));
}
return out;

// Parse Previous Themes 2026-06-10 — tema-kontinuitet.
// Läser de senaste arkiverade veckorna ur Notion-arkivet som kontext till syntesen.
// Notion otillgängligt => tomt resultat och logg — INGEN bortfallsmarkör i mailet,
// eftersom kontinuitet är en förbättring och inte ett källberoende.
const resp = $input.first().json || {};
const config = $('Detect Execution Mode').first().json;
const weeks = [];
try {
  if (resp.error !== undefined) throw new Error(typeof resp.error === 'string' ? resp.error : JSON.stringify(resp.error).substring(0, 120));
  const pages = resp.results || [];
  for (const p of pages) {
    const props = p.properties || {};
    const datum = (props['Datum'] && props['Datum'].date) ? props['Datum'].date.start : '';
    // Hoppa över sidor från innevarande period (självreferens vid omkörning samma vecka)
    if (datum && config.dateTo && datum >= config.dateTo) continue;
    const summary = ((props['Sammanfattning'] || {}).rich_text || []).map(t => t.plain_text || '').join('');
    const themes = ((props['Teman'] || {}).multi_select || []).map(t => t.name);
    const vecka = (props['Vecka'] || {}).number;
    const period = ((props['Period'] || {}).rich_text || []).map(t => t.plain_text || '').join('');
    if (themes.length || summary) weeks.push({ type: 'previous_week', vecka, period, datum, summary, themes });
    if (weeks.length >= 3) break;
  }
} catch (e) {
  console.log('Tema-kontinuitet: kunde inte läsa arkivet, fortsätter utan. ' + e.message);
}
if (weeks.length === 0) return [{ json: { isEmpty: true, source: 'Notion-arkiv' } }];
return weeks.map(w => ({ json: w }));
